<script setup>
import { formatSize } from '@/utils/util'
import { uploadLongCodeFile, cleanLongCodeFile } from '@/services/knowledge'

const loading = ref(false)
const uploaderRef = ref()

const fileList = ref([])
function onFileSelect() {
  fileList.value = []
}

function removeFile() {
  fileList.value = []
  cleanLongCodeFile()
}

const fileUploader = (event) => {
  const formData = new FormData()
  event.files.forEach((file) => {
    formData.append('file', file)
  })
  loading.value = true
  fileList.value = []
  uploadLongCodeFile(formData)
    .then(() => {
      fileList.value = event.files
      uploaderRef.value.clear()
      uploaderRef.value.uploadedFileCount = 0
    })
    .finally(() => {
      loading.value = false
    })
}
</script>

<template>
  <div class="file-container w-full flex flex-col justify-start items-start">
    <FileUpload
      mode="basic"
      name="uploader"
      ref="uploaderRef"
      url=""
      accept=".zip"
      :choose-label="$t('kb.selectFile')"
      upload-icon="pi pi-file"
      :maxFileSize="50 * 1024 * 1024"
      auto
      customUpload
      @uploader="fileUploader"
      @select="onFileSelect"
      :disabled="loading"
      :pt="{
        chooseButton: {
          class: 'p-button-text'
        }
      }"
    >
      <template #uploadicon>
        <i class="pi pi-spin pi-spinner mr-1" v-if="loading"></i>
        <i class="pi pi-file mr-1" v-else></i>
      </template>
    </FileUpload>
    <div class="flex items-center w-full mt-2 cursor-pointer" v-if="fileList.length > 0">
      <i class="pi pi-file text-4xl"></i>
      <div>
        <div class="w-56 break-all whitespace-nowrap overflow-hidden text-ellipsis">{{ fileList[0].name }}</div>
        <div>{{ formatSize(fileList[0].size) }}</div>
      </div>
      <div class="ml-4">
        <Button icon="pi pi-times" @click="removeFile()" rounded text severity="danger" />
      </div>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
